mapper.select:
SELECT c.id, c.article_id, a.title AS article_title, c.parent_id, c.nickname, c.email, c.website, c.content, c.quote_text, c.quote_start, c.quote_end, c.ip_region, c.status, c.is_admin, c.create_time FROM blog_comment c LEFT JOIN blog_article a ON a.id = c.article_id AND a.is_deleted = 0
c.is_deleted = 0
AND c.article_id = #{queryParams.articleId}
AND c.status = #{queryParams.status}
AND ( c.nickname LIKE CONCAT('%', #{queryParams.keywords}, '%') OR c.content LIKE CONCAT('%', #{queryParams.keywords}, '%') OR c.quote_text LIKE CONCAT('%', #{queryParams.keywords}, '%') )
ORDER BY c.create_time DESC, c.id DESC
